from research_helpers import *
a=ev('https://www.sec.gov/Archives/edgar/data/907654/000121390025021165/ea0230445-10k_orukathe.htm','ARCA public registrant completed merger and renamed Oruka August 29 2024; current operating subsidiary distinguished from parent.')
b=ev('https://www.sec.gov/Archives/edgar/data/907654/000121390024069662/ea0211472-8k425_arcabio.htm','Agreement to transfer legacy Gencaro/rNAPc2 assets to Genvara; historical developer link retained, no unverified closing date.')
c=ev('https://www.sec.gov/Archives/edgar/data/907654/000156459018021065/abio-10q_20180630.htm','Historical AB171 thiol-substituted isosorbide mononitrate research candidate.')
d=ev('https://ir.orukatx.com/news-releases/news-release-details/oruka-therapeutics-reports-second-quarter-2026-financial-results','August 2026 update names ORKA-001 IL23, ORKA-002 IL17A/F and new TL1A ORKA-004. May licence amendment broadens ORKA-001 to all areas. Future trials not assumed already started.')
e=ev('https://orukatx.com/wp-content/uploads/2026/06/Oruka-Corporate-Deck-June-2026.pdf','Historical ORKA-003 undisclosed programme and ORKA-021 sequential 002/001 regimen. Combination not another molecule; no unsupported 003=004 equivalence.')
products=[p('Gencaro','Historical bucindolol hydrochloride programme.',b,aliases=['Bucindolol hydrochloride'],evidence=[a,b]),p('rNAPc2','Historical recombinant nematode anticoagulant protein c2 programme.',b,aliases=['AB201'],evidence=[a,b]),p('AB171','Historical genetically targeted cardiovascular research compound.',c)]
for name,desc,life in [('ORKA-001','Investigational long-acting IL-23p19 antibody.','development'),('ORKA-002','Investigational long-acting IL-17A/F antibody.','development'),('ORKA-004','Announced TL1A antibody programme; initial clinic entry projected.','development')]:products.append(p(name,desc,d,life=life,roles=['commercial_partner'],evidence=[a,d]))
products += [p('ORKA-003','Undisclosed historical Oruka programme; relation to ORKA-004 unresolved.',e,roles=['commercial_partner'],evidence=[a,e]),p('ORKA-021','Named sequential regimen of ORKA-002 and ORKA-001, not a third molecule.',e,life='research',roles=['commercial_partner'],attributes={'programme_kind':'combination_regimen'},evidence=[a,e])]
co=dict(company_id='cmp_2ade2da9-cc8f-41ff-9c95-b267036e320b',products=products,evidence=[a,b,c,d,e],status='partial',coverage_note='Three legacy ARCA candidates and five current/historical Oruka molecules/programmes linked to same renamed public parent, supported by SEC legal identity. Operating-subsidiary assets associated as commercial partner. ORKA-021 is explicitly a regimen, not another molecule; ORKA-003 not silently renamed 004 without proof. Partial: Genvara asset closing/current status, full predecessor programmes, September/October 2026 updates and candidate-name equivalences remain. No company identity table merge or name edit performed.')
(out/'batch-0344.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
